      "id": "rev-03",
      "author": "Анастасия Р.",
      "date": "02.07.2025",
      "text": "Хочу выразить большую благодарность команде Re.source clinic. Наконец-то современность вошла в нашу жизнь! Я обратилась с просьбой сделать базовый Чек ап по анализам, цена была просто подарок Божий. Список необходимых показателей, подобрали клинику для сдачи анализов, самую близкую и удобную мне,пришла, сдала и никаких нервов, никакой беготни из кабинета в кабинет. После дождались результатов анализов и назначили консультацию с врачом и нутрициологом. Встреча прошла в Zoom, все удобно, комфортно, врачи очень хорошие, расшифровали каждый пункт анализа, сказали как должно быть, что где нужно подтянуть. Было много обсуждений и рекомендаций, мне очень понравилось, великолепный подход, самое главное, я теперь точно знаю какие витамины мне нужны, а какие нет. Еще раз большое спасибо, буду каждый год делать такой Чек Ап и семью всю проверю 🙏🏻❤️\nВсе без лести, я очень рада,что есть такие клиники как вы. Вы подливаете и облегчаете нам жизнь 🫶🏻",
      "result": "Чек-ап: расшифровали каждый показатель, подобрали витамины",
