      "text": "Занимаюсь 4-и месяц с клиникой Resource на индивидуальной программе с нутрициологом и эндокринологом. Разработали мне подходящую программу питания, режим тренировок и поддержку бадами на основании моих анализов, жалоб и целей.\nРезультатами очень довольна: похудела, вес держится, пищевые привычки стали более здоровыми, энергия на уровне о сейчас в планах только поднабрать мышечной массы, поэтому добавила больше силовых тренировок. Получилось улучшить режим дня: ложусь и засыпаю стабильно раньше, и просыпаюсь пораньше и легче. По иммунитету тоже, тьфу-тьфу лучше стало, за 4 месяца один раз по лайту простуда была.\nДля тех, кто тоже хочет быть стройным и здоровым, от души рекомендую RE:SOURCE ❤️",
