      "id": "rev-12",
      "author": "Юлия А.",
      "date": "29.12.2024",
      "text": "Добрый вечер!\nХочу поблагодарить за совместную работу над моим здоровьем.\nза время программы, я разобралась с пользой тех или иных продуктов, как они влияют на мой организм, поняла причинно-следственные связи, что позволяет мне в будущем самостоятельно управлять своим рационом.\nВрач Алина, и нутрициолог Екатерина оперативно отвечали на мои вопросы, поясняли и гибко корректировали программу с учетом моих условий жизни. Что очень важно, ведь идеальных условий не существует.\nя обрела новые полезные пищевые привычки, но так скажем поддерживала их, ведь под наблюдением с этого словно не слиться. Стала следить за приемами пищи, раньше могла пропускать и не придавать значения и по итогу переедала. Я довольна результатами работы, на текущий момент с жкт нет проблем, если соблюдаю свой режим. И важно что в период сильного стресса мой организм не свалился в болезнь, думаю питание тоже в этом сыграло свою роль.\nтак что благодарю! С Новым годом! 🎄",
