      "id": "rev-25",
      "author": "Елена З.",
      "date": "19.02.2023",
      "text": "Я пришла с запросом уменьшить вес, по возможности слезть с гормонов и чтобы самочувствие стало лучше.\nДо этого был опыт работы с частными нутрициологами и были разные результаты и я примерно понимала что меня ждёт. Но так, чтобы это была клиника, у меня впервые.\nИ конечно в этом сразу было отличие – от сбора информации о моём здоровье, до разбора анализов. Более тщательный и внимательный подход.\nЕлена меня покорила с первой же конституции – очень чувствовался профессионализм и забота❤️\nИ особая благодарность за составление для меня постного меню – для меня это было очень важно и особенно ценно – чтобы во время поста, который я регулярно соблюдаю, моё питание было сбалансированным! И такое для меня делают впервые🙏🏻\nЧто изменилось за эти два месяца программы?\nВыработалась дисциплина и понимание сколько раз я должна в день есть и главное, что я должна есть. Какие продукты мне во благо, а какие лучше не употреблять.\nУлучшилось общее самочувствие, появилось больше энергии, кожа по ощущениям стала менее рыхлой и более гладкой. Начала регулярно 3 раза в неделю заниматься спортом.\nДаже муж заметил, что я стала более энергичной⚡️\nВес сильно не изменился, пока минус 2 кг, но объёмы ушли минус 4 см в талии, 2 см в бёдрах, 1 см в руках и ногах и это очень заметно.\nЯ понимаю, что при сохранении результатов и планов в новом году вес будет уходить, учитывая что у меня теперь есть стратегия в отношении здорового питания и рекомендации по закрытию дефицитов!\nКлинику с удовольствием рекомендую – рассказываю о ней у себя в соц сетях и лично рекомендовала и буду рекомендовать людям❤️🙏🏻✨\nТак как именно здесь пол года вновь вернулся мой ресурс⚡️\nПрограмма действительно стоила того и это мой самый ценный подарок для меня, за весь прошлый год! Благодарю Александру и всю её команду от всей души🙏🏻🙏🏻🙏🏻💓💓\nЖелаю клинике и клиники процветания, только расти и расширяться и побольше благодарных и дисциплинированных клиентов🙏🏻✨\nС уважением и любовью\nЕлена Зверянская.",
