      "id": "rev-26",
      "author": "Элеонора Ф.",
      "date": "18.02.2023",
      "text": "Добрый день! Я пришла в клинику с запросом поднять уровень энергии, второстепенной задачей было скинуть набранные за прошлый год килограммы. Диеты я никогда особо не любила, поэтому их пробовать не хотелось, после консультации мне захотелось попробовать предлагаемую ей программу. Что мне понравилось – меня не ограничивали в количестве съеденной еды, в виде мяса, которое можно есть, дали рекомендации по режиму дня, физической нагрузке и т.д. Далее уже все зависело от меня и моего желания добиться поставленных результатов. Я стала выполнять рекомендации специалистов, стала больше ходить пешком, хотя раньше очень мало ходила, начала правильно питаться, режим соблюдать и вес пошел вниз. За 2 месяца программы я похудела почти на 10 кг, у меня улучшилась кожа, появилась сила, стала более активной и жизнерадостной, что самое важное! Благодарна Камиллу и Дарью, которые меня сопровождали всю программу, они всегда давали мне ценные советы и указания!)\n🔥🔥",
