      "id": "rev-31",
      "author": "Анна П.",
      "date": "27.09.2022",
      "text": "В конце августа этого года я начала проходить программу. У меня были такие запросы: 1. Узнать почему у меня болит живот (как оказалось это проблемы с жкт); 2. Решить проблемы с репродуктивной системой; 3. Проблемы с кожей. Весной 2021 я увидела в тик токе видео Александры, перешла в профиль инстаграмма и записалась к ней на консультацию. Тогда я узнала как питаться, чтобы насыщать организм всем важным для него, зачем нужны добавки и тогда мне хотелось немного скинуть вес. После того как я прошла программу, у меня была такая кожа чудесная это просто был 🔥🔥🔥 и вес тоже ушёл. Хоть я и шла больше за знаниями в сфере здоровья, но получила я намного больше. Потом весной 2022 меня стал активно беспокоить живот, поэтому стала ходить по врачам, от чего мне стало ещё хуже. Последней надеждой была AB clinic. На данный момент прошёл всего лишь месяц, а у меня уже решились проблемы с животом. Представьте, что он мне вообще не болит. Это просто какая-то магия, я безумна рада, что проблема решилась. Впереди ещё больше месяца активной работы, за этот период я очень надеюсь, что решатся две другие мои проблемы. Хочется ещё рассказать о самом подходе к работе клиники: все безупречно и налажено, каждый работник отвечает за свои обязанности, формальности проходят быстро. Очень чувствуется слаженная работа у коллектива. Теперь о самом прохождении: сначала я прошла тесты, результат которых не заставил меня долго ждать, затем мне составили программу и назначили консультацию. На этой консультации мне подробнейшим образом рассказали о моем организме все от А до Я, и делая акцент на мои запросы. Потом добавили в чат, там мне нутрициолог отвечала очень подробно и развёрнуто на определённый спектр моих вопросов и периодически спрашивала как мое состояние (это было приятно🌟). Я сразу почувствовала, что не зря пришла, поскольку вёлся активный образ жизни и мы представляли с сбалансированном питании. Необычным для меня я узнала, что у меня огромный «сосуд», в котором тоже могут быть высыпания. Я стала больше следить за здоровьем организма в целом. В самом начале у меня не хватало привычки выпивать перекусывать, мне достаточно трёх основных приёма пищи, а иногда четырёх. Я безумно благодарна всей команде и Александре в отдельности за проделанную работу, за мой результат, за внутреннюю и наружную работу с организмом, другим словом благодарю 🙏. Я считаю, что это прекрасное место необходимо каждому, кто хочет улучшить свое здоровье и приобрести полезные привычки!",
