      "id": "rev-32",
      "author": "Екатерина Х.",
      "date": "01.08.2022",
      "text": "Хочу начать с того, что я сто раз пыталась похудеть, перепробовала много всего, и каждый раз это было быстро и не надолго. Все ненавистные кг возвращались обратно также быстро, как и скидывались, и к ним, как правило, прибавлялось ещё несколько плюсом. С годами это как снежный ком, похудеть становилось всё сложнее, и проявляло другие проблемы, которые были связаны уже со здоровьем, щитовидка, гормоны, высыпания на коже... и прочее. На программу я пришла случайно, увидела рекламу в Инстаграм, решила почитать, так я вышла на Александру. В дальнейшем у нас состоялась зум-встреча, и сразу после встречи я купила программу на три месяца. Мне были направлены опросники, которые необходимо было заполнить, и уже на основании моих ответов был определён ряд проблем, и составлен список показателей для сдачи анализов. Клиника направляет гарантийное письмо, сдаёшь анализы, дожидаешься результатов и потом уже состоится консультация с врачом-нутрициологом. Хочу отметить, что именно эта встреча была самой приятной, и работа с Камилой это отдельное удовольствие. Она очень внимательная, все подробно объясняет и просто расшифровывает каждую мелочь! Камила, спасибо Вам большое. Так же хочу отметить, что работать с куратором на протяжении двух месяцев мне было не комфортно. Мне не всегда отвечали, особенно в субботу, хотя это рабочий день. Также рекомендацией было, чтобы перед сном не сидеть в телефонах, не смотреть телевизор, лучше почитать, подготовить себя ко сну, а в итоге в половине случаев я должна была отвечать на вопросы куратора. И хочу отметить невнимательность куратора, я все рекомендации всегда описывала и рацион, и занятия, и другие ситуации, но девушка куратор задавала мне вопросы о том, что я и так написала, ощущение возникало, что просто человек просматривал мои тарелки еды, а текст не читал! И прекрасно, что последние две недели данного куратора заменила сама Камила, самый приятный и ответственный врач. По итогу за три месяца программы я похудела на 8 кг лишним кг, мой объём значительно уменьшился (ОГ минус 8см; ОТ -8,5см; ОБ -7см; ОН -6см; ОР -3,5см; ОЗ -1,5см) И ведь я не голодала, я вкусно и сытно питалась только правильными продуктами, и могу точно сказать, что за эти три месяца мои привычки в еде очень изменились, за что большое спасибо!",
