      "author": "Елена А.",
      "date": "18.01.2022",
      "text": "Результаты и ощущения:\n1.Вес снизился до 68 кг (-6 кг), талия уменьшилась на 2 см, практически не было физ. нагрузки\n2.Стул и пищеварение – регулярно, думаю благодаря пробиотикам\n3.Слабость и сонливость остались, особенно после обеда и ужина\n4.Высыпания на коже ещё остаются – работаю ещё с косметологом\n5.Пищевые привычки изменились и укрепились, чему очень рада\nПонимаю, что 3 месяца мало для кардинальных изменений, буду продолжать соблюдать протоколы питания и подключу спорт",
      "result": "−6 кг (до 68 кг) и −2 см в талии",
